  // Full translations for guided hints and explained solutions.
  EN["Commence par calculer le réseau de PC-A. Avec /24, les 3 premiers octets représentent le réseau."] = "Start by calculating PC-A's network. With /24, the first 3 octets represent the network."; ES["Commence par calculer le réseau de PC-A. Avec /24, les 3 premiers octets représentent le réseau."] = "Empieza calculando la red de PC-A. Con /24, los 3 primeros octetos representan la red.";
  EN["PC-A est dans 192.168.10.0/24. Les hôtes usuels vont de 192.168.10.1 à 192.168.10.254."] = "PC-A is in 192.168.10.0/24. Usable hosts range from 192.168.10.1 to 192.168.10.254."; ES["PC-A est dans 192.168.10.0/24. Les hôtes usuels vont de 192.168.10.1 à 192.168.10.254."] = "PC-A está en 192.168.10.0/24. Los hosts utilizables van de 192.168.10.1 a 192.168.10.254.";
  EN["Choisis par exemple 192.168.10.50/24. N'utilise ni .0 (réseau), ni .255 (broadcast), ni l'adresse déjà prise .20."] = "For example, choose 192.168.10.50/24. Do not use .0 (network), .255 (broadcast), or the already used .20 address."; ES["Choisis par exemple 192.168.10.50/24. N'utilise ni .0 (réseau), ni .255 (broadcast), ni l'adresse déjà prise .20."] = "Por ejemplo, elige 192.168.10.50/24. No uses .0 (red), .255 (broadcast) ni la dirección .20 ya utilizada.";
  EN["Regarde dans quel bloc tombent 65 et 126. Le bloc doit commencer avant 65 et finir après 126."] = "Look at which block contains 65 and 126. The block must start before 65 and end after 126."; ES["Regarde dans quel bloc tombent 65 et 126. Le bloc doit commencer avant 65 et finir après 126."] = "Mira en qué bloque caen 65 y 126. El bloque debe empezar antes de 65 y terminar después de 126.";
