  EN["65 et 126 sont tous les deux dans 64–127 : le réseau est 10.0.0.64/26. Un /27 les séparerait."] = "65 and 126 are both inside 64–127: the network is 10.0.0.64/26. A /27 would separate them."; ES["65 et 126 sont tous les deux dans 64–127 : le réseau est 10.0.0.64/26. Un /27 les séparerait."] = "65 y 126 están ambos en 64–127: la red es 10.0.0.64/26. Un /27 los separaría.";
  EN["Un /27 avance par blocs de 32 : 0, 32, 64, 96…"] = "A /27 advances in blocks of 32: 0, 32, 64, 96…"; ES["Un /27 avance par blocs de 32 : 0, 32, 64, 96…"] = "Un /27 avanza en bloques de 32: 0, 32, 64, 96…";
  EN["172.16.4.33/27 appartient au réseau 172.16.4.32/27. Broadcast : .63. Hôtes : .33 à .62."] = "172.16.4.33/27 belongs to network 172.16.4.32/27. Broadcast: .63. Hosts: .33 to .62."; ES["172.16.4.33/27 appartient au réseau 172.16.4.32/27. Broadcast : .63. Hôtes : .33 à .62."] = "172.16.4.33/27 pertenece a la red 172.16.4.32/27. Broadcast: .63. Hosts: .33 a .62.";
  EN["Choisis deux adresses libres entre .34 et .62, par exemple .40 et .50."] = "Choose two free addresses between .34 and .62, for example .40 and .50."; ES["Choisis deux adresses libres entre .34 et .62, par exemple .40 et .50."] = "Elige dos direcciones libres entre .34 y .62, por ejemplo .40 y .50.";
  EN["Une passerelle doit être dans le même réseau local que l'hôte qui l'utilise."] = "A gateway must be in the same local network as the host using it."; ES["Une passerelle doit être dans le même réseau local que l'hôte qui l'utilise."] = "Una gateway debe estar en la misma red local que el host que la utiliza.";
  EN["Le routeur possède 192.168.1.1/24 côté PC-A et 192.168.2.1/24 côté PC-B."] = "The router has 192.168.1.1/24 on the PC-A side and 192.168.2.1/24 on the PC-B side."; ES["Le routeur possède 192.168.1.1/24 côté PC-A et 192.168.2.1/24 côté PC-B."] = "El router tiene 192.168.1.1/24 del lado de PC-A y 192.168.2.1/24 del lado de PC-B.";
