  EN["R1: 192.168.20.0/24 via 10.0.0.2. R2: 192.168.10.0/24 via 10.0.0.1."] = "R1: 192.168.20.0/24 via 10.0.0.2. R2: 192.168.10.0/24 via 10.0.0.1."; ES["R1: 192.168.20.0/24 via 10.0.0.2. R2: 192.168.10.0/24 via 10.0.0.1."] = "R1: 192.168.20.0/24 vía 10.0.0.2. R2: 192.168.10.0/24 vía 10.0.0.1.";
  EN["Choisis d'abord le plus grand réseau. 50 hôtes demandent au moins 62 adresses hôtes usuelles : /26. 20 hôtes demandent /27."] = "Choose the largest network first. 50 hosts require at least 62 usual host addresses: /26. 20 hosts require /27."; ES["Choisis d'abord le plus grand réseau. 50 hôtes demandent au moins 62 adresses hôtes usuelles : /26. 20 hôtes demandent /27."] = "Elige primero la red más grande. 50 hosts necesitan al menos 62 direcciones de host: /26. 20 hosts necesitan /27.";
  EN["Un /26 occupe 64 adresses et doit commencer sur 0, 64, 128 ou 192. Un /27 occupe 32 adresses et commence sur un multiple de 32."] = "A /26 uses 64 addresses and must start at 0, 64, 128 or 192. A /27 uses 32 addresses and starts on a multiple of 32."; ES["Un /26 occupe 64 adresses et doit commencer sur 0, 64, 128 ou 192. Un /27 occupe 32 adresses et commence sur un multiple de 32."] = "Un /26 ocupa 64 direcciones y debe empezar en 0, 64, 128 o 192. Un /27 ocupa 32 direcciones y empieza en un múltiplo de 32.";
  EN["Exemple simple : LAN A 10.42.0.0/26 (.0–.63), LAN B 10.42.0.64/27 (.64–.95)."] = "Simple example: LAN A 10.42.0.0/26 (.0–.63), LAN B 10.42.0.64/27 (.64–.95)."; ES["Exemple simple : LAN A 10.42.0.0/26 (.0–.63), LAN B 10.42.0.64/27 (.64–.95)."] = "Ejemplo simple: LAN A 10.42.0.0/26 (.0–.63), LAN B 10.42.0.64/27 (.64–.95).";
  EN["Le /25 existant occupe 192.168.50.0 à 192.168.50.127. Toute nouvelle plage doit commencer après .127."] = "The existing /25 occupies 192.168.50.0 to 192.168.50.127. Any new range must start after .127."; ES["Le /25 existant occupe 192.168.50.0 à 192.168.50.127. Toute nouvelle plage doit commencer après .127."] = "El /25 existente ocupa 192.168.50.0 a 192.168.50.127. Cualquier rango nuevo debe empezar después de .127.";
  EN["50 hôtes ⇒ /26 minimum. Les frontières /26 du dernier octet sont 0, 64, 128 et 192."] = "50 hosts ⇒ /26 minimum. /26 boundaries in the last octet are 0, 64, 128 and 192."; ES["50 hôtes ⇒ /26 minimum. Les frontières /26 du dernier octet sont 0, 64, 128 et 192."] = "50 hosts ⇒ /26 mínimo. Los límites /26 del último octeto son 0, 64, 128 y 192.";
  EN["192.168.50.128/26 ou 192.168.50.192/26 conviennent : leurs plages ne croisent pas le /25 existant."] = "192.168.50.128/26 or 192.168.50.192/26 work: their ranges do not cross the existing /25."; ES["192.168.50.128/26 ou 192.168.50.192/26 conviennent : leurs plages ne croisent pas le /25 existant."] = "192.168.50.128/26 o 192.168.50.192/26 sirven: sus rangos no cruzan el /25 existente.";
  EN["Découpe le problème en 3 : LAN A↔LAN B, LAN A→Internet, puis le chemin retour."] = "Split the problem into 3 parts: LAN A↔LAN B, LAN A→Internet, then the return path."; ES["Découpe le problème en 3 : LAN A↔LAN B, LAN A→Internet, puis le chemin retour."] = "Divide el problema en 3 partes: LAN A↔LAN B, LAN A→Internet y después el camino de vuelta.";
