  EN["LAN A gw 10.1.0.1 ; R1: 10.2.0.0/24 via 172.16.0.2 et défaut via 172.16.0.2 ; R2: 10.1.0.0/24 via 172.16.0.1 et défaut via 198.51.100.1."] = "LAN A gw 10.1.0.1; R1: 10.2.0.0/24 via 172.16.0.2 and default via 172.16.0.2; R2: 10.1.0.0/24 via 172.16.0.1 and default via 198.51.100.1."; ES["LAN A gw 10.1.0.1 ; R1: 10.2.0.0/24 via 172.16.0.2 et défaut via 172.16.0.2 ; R2: 10.1.0.0/24 via 172.16.0.1 et défaut via 198.51.100.1."] = "LAN A gw 10.1.0.1; R1: 10.2.0.0/24 vía 172.16.0.2 y por defecto vía 172.16.0.2; R2: 10.1.0.0/24 vía 172.16.0.1 y por defecto vía 198.51.100.1.";
  EN["Taille d'abord : 100→/25, 50→/26, 20→/27."] = "Start with sizes: 100→/25, 50→/26, 20→/27."; ES["Taille d'abord : 100→/25, 50→/26, 20→/27."] = "Empieza por los tamaños: 100→/25, 50→/26, 20→/27.";
  EN["Une disposition simple est .0/25, .128/26 puis .192/27."] = "A simple layout is .0/25, .128/26, then .192/27."; ES["Une disposition simple est .0/25, .128/26 puis .192/27."] = "Una disposición sencilla es .0/25, .128/26 y luego .192/27.";
  EN["Compare toujours les plages complètes : réseau → broadcast."] = "Always compare complete ranges: network → broadcast."; ES["Compare toujours les plages complètes : réseau → broadcast."] = "Compara siempre los rangos completos: red → broadcast.";
  EN["Sépare le trafic LAN C du trafic Internet."] = "Separate LAN C traffic from Internet traffic."; ES["Sépare le trafic LAN C du trafic Internet."] = "Separa el tráfico de LAN C del tráfico de Internet.";
  EN["LAN C = 172.20.30.0/24 via R2. Le reste = 0.0.0.0/0 via FAI."] = "LAN C = 172.20.30.0/24 via R2. Everything else = 0.0.0.0/0 via ISP."; ES["LAN C = 172.20.30.0/24 via R2. Le reste = 0.0.0.0/0 via FAI."] = "LAN C = 172.20.30.0/24 vía R2. El resto = 0.0.0.0/0 vía ISP.";
  EN["Un next hop doit être directement joignable par le routeur qui l'utilise."] = "A next hop must be directly reachable by the router that uses it."; ES["Un next hop doit être directement joignable par le routeur qui l'utilise."] = "Un next hop debe ser alcanzable directamente por el router que lo utiliza.";
  EN["Dessine mentalement le trajet A→R1→R2→R3→C puis C→R3→R2→R1→A."] = "Mentally draw A→R1→R2→R3→C, then C→R3→R2→R1→A."; ES["Dessine mentalement le trajet A→R1→R2→R3→C puis C→R3→R2→R1→A."] = "Dibuja mentalmente A→R1→R2→R3→C y luego C→R3→R2→R1→A.";
  EN["R2 a besoin de deux routes : une vers chaque LAN."] = "R2 needs two routes: one to each LAN."; ES["R2 a besoin de deux routes : une vers chaque LAN."] = "R2 necesita dos rutas: una hacia cada LAN.";
  EN["Le next hop est toujours le voisin immédiat, jamais le routeur deux sauts plus loin."] = "The next hop is always the immediate neighbor, never a router two hops away."; ES["Le next hop est toujours le voisin immédiat, jamais le routeur deux sauts plus loin."] = "El next hop siempre es el vecino inmediato, nunca un router a dos saltos.";
  EN["Le réseau réservé occupe exactement .64→.127."] = "The reserved network occupies exactly .64→.127."; ES["Le réseau réservé occupe exactement .64→.127."] = "La red reservada ocupa exactamente .64→.127.";
